import numpy as np
from scipy.ndimage import label
a=np.array(a)
for c in [2,4,7,9]:
 lab,n=label(a==c)
 print('\ncolor',c)
 for i in range(1,n+1):
  pts=np.argwhere(lab==i)
  if len(pts)>1: print(len(pts),(pts.min(0).tolist(),pts.max(0).tolist()),pts.tolist())

for br in range(7):
 for bc in range(7):
  block=a[br*3:br*3+3,bc*3:bc*3+3]
  pts=[(int(r-br*3),int(c-bc*3),int(a[r,c])) for r,c in np.argwhere((block!=0)&(block!=5))]
  if pts: print((br,bc),pts)

for br in range(7):
 for bc in range(7):
  block=a[br*3:br*3+3,bc*3:bc*3+3]
  pts=[(int(r),int(c),int(block[r,c])) for r,c in np.argwhere((block!=0)&(block!=5))]
  if pts: print((br,bc),pts)
